def canCompleteCircuit(gas, cost):
    """
    Find starting gas station index to complete the circular route.
    Returns -1 if impossible.
    """
    if sum(gas) < sum(cost):
        return -1

    start, fuel = 0, 0
    for i in range(len(gas)):
        if fuel + gas[i] - cost[i] < 0:
            # Can't reach next station, reset start
            start, fuel = i + 1, 0
        else:
            # Can reach next station, update fuel
            fuel += gas[i] - cost[i]

    return start
